syntax = "proto3";
package pd;
import "options_extension.proto";

/*
 * 网络协议和DataDefine公用的枚举
 * 说明：
 * 1. 只支持枚举公用，不支持message
 * 2. 枚举命名保持统一
 * 3. 只能在 ABC_Project/${BRANCH}/Protobuf 下对此文件进行修改。服务器 abc_proto 下的修改会被覆盖
 * 4. 管线会将此文件同步到服务器 abc_proto 目录下并重命名为 common.enum.proto，同时修改作用域为 packet proto，实现 DataDefine 与网络协议命名空间隔离
 */

// 玩家基础属性
enum PlayerAttrType
{
    PLAYER_ATTR_TYPE_NONE = 0;          // 非法
    PLAYER_ATTR_TYPE_MIGHT = 1;         // 威力
    PLAYER_ATTR_TYPE_CHARM = 2;         // 魅力
    PLAYER_ATTR_TYPE_INTELLIGENCE = 3;  // 智力
    PLAYER_ATTR_TYPE_LUCK = 4;          // 幸运
}

// Stage 战斗结果，由服务器基于Round结果结算得到
enum BattleEndStatus
{
    BATTLE_END_STATUS_NONE = 0;
    BATTLE_END_STATUS_WIN = 1;
    BATTLE_END_STATUS_LOSE = 2;
    BATTLE_END_STATUS_QUIT = 3;  // 玩家退出
}

// Round 回合战斗结果，由客户端上报得到
enum BattleRoundEndStatus
{
    BATTLE_ROUND_END_STATUS_NONE = 0;
    BATTLE_ROUND_END_STATUS_WIN = 1;
    BATTLE_ROUND_END_STATUS_LOSE = 2;
    BATTLE_ROUND_END_STATUS_DRAW = 3;  // 平局
}

// Round 回合战斗结束细节，由客户端上报得到
enum BattleRoundEndDetail
{
    BATTLE_ROUND_END_DETAIL_NONE = 0;                   // 无效
    BATTLE_ROUND_END_DETAIL_ALL_HOME_DEAD = 1;          // 己方全灭
    BATTLE_ROUND_END_DETAIL_ALL_AWAY_DEAD = 2;          // 敌方全灭
    BATTLE_ROUND_END_DETAIL_TIMEOUT = 3;                // 超时
    BATTLE_ROUND_END_DETAIL_SURVIVED_SUCC = 4;          // 生存成功
    BATTLE_ROUND_END_DETAIL_HOME_VIP_KILLED = 5;        // 己方 VIP 被击杀
    BATTLE_ROUND_END_DETAIL_AWAY_VIP_KILLED = 6;        // 敌方 VIP 被击杀
    BATTLE_ROUND_END_DETAIL_OCCUPY_MORE_GRID_SUCC = 7;  // 占领更多格子成功
    BATTLE_ROUND_END_DETAIL_OCCUPY_MORE_GRID_FAIL = 8;  // 占领更多格子失败
    BATTLE_ROUND_END_DETAIL_CUSTOM_WIN = 9;             // 玩法自定义胜利
    BATTLE_ROUND_END_DETAIL_CUSTOM_LOSE = 10;           // 玩法自定义失败
}

enum MainMissionStatus
{
    MAIN_MISSION_STATUS_NONE = 0;
    MAIN_MISSION_STATUS_DOING = 1;
    MAIN_MISSION_STATUS_SUCC = 2;
    MAIN_MISSION_STATUS_SUSPEND = 3;  // 挂起（DOING<->SUSPEND）
}

enum MissionObjectiveStatus
{
    MISSION_OBJECTIVE_STATUS_NONE = 0;
    MISSION_OBJECTIVE_STATUS_DOING = 1;
    MISSION_OBJECTIVE_STATUS_SUSPEND = 2;  // 挂起（DOING<->SUSPEND）
    MISSION_OBJECTIVE_STATUS_CLOSE = 3;
    MISSION_OBJECTIVE_STATUS_SUCC = 4;
}

enum SubMissionStatus
{
    SUB_MISSION_STATUS_NONE = 0;
    SUB_MISSION_STATUS_DOING = 1;
    SUB_MISSION_STATUS_SUCC = 2;     // 正常完成
    SUB_MISSION_STATUS_CLOSE = 3;    // 强制关闭

syntax = "proto3";
package pd;
import "google/protobuf/descriptor.proto";
import public "google/protobuf/any.proto";

// file options [50000, 51000)
extend google.protobuf.FileOptions
{
    ProtoFileType file_type = 50000;
    // ProtoGenPolicy file_gen_policy = 50001;
}

/*
 * cli_ 表示客户端专用
 * svr_ 表示服务器专用
 */

// message options [51000, 52000)
extend google.protobuf.MessageOptions
{
    MessageGenPolicy message_gen_policy = 51000;
    string super_field_name = 51001;
    ProtoDataLoader data_loader = 51002;
    string cli_message_sharp_type = 51003;
    bool cli_editor_message = 51004;        // 是否是编辑器消息
    string cli_message_attributes = 51005;  // 消息属性
    bool node_is_action = 51006;            // Node是否是Action
    bool node_is_tick = 51007;              // Node是否Tick
    bool cli_allow_set = 51008;             // 是否运行设置字段
    string cli_index_field_name = 51009;    // 索引字段名
    NodeFlow node_flow = 51010;             // Node流向
    bool serialize_allow_write = 51011;
    string svr_index_field_name = 51014;        // 索引字段名列表，逗号分隔(服务器用)。只能定义当前message内的field，或父类中的field，且需注意继承关系中的message是否包含该同名字段
    bool cli_ignore_preload_type = 51015;       // 是否忽略GenPreloadFunc
    bool finish_type_backtrack = 51016;         // 完成条件是否可回溯
    ConditionOwner condition_owner = 51017;     // Condition逻辑归属
    GraphNodeType node_type = 51018;            // GraphNode类型
    FinishTypeOwner finish_type_owner = 51019;  // finish type所属
    string cli_message_tooltip = 51021;         // C# 类型ToolTip
    ChallengeGoalFinishType challenge_goal_finish_type = 51022;
    bool svr_is_extra_filter_base = 51023;                     // 是否生效服务器额外过滤器(基类)
    bool svr_is_extra_filter_derived = 51024;                  // 是否生效服务器额外过滤器(子类)
    bool svr_is_unordered_map = 51025;                         // 是否是unordered_map类型
    bool cli_editor_hidden = 51026;                            // 在编辑器中隐藏该配置（不可见且不自动创建）
    bool cli_message_support_streaming_serialization = 51027;  // 是否额外支持Streaming序列化
    bool cli_serialize_allow_editor_write = 51028;             // 是否允许Editor下序列化写入
}

// field options [52000, 53000)
extend google.protobuf.FieldOptions
