syntax = "proto3";
package pd;

import public "options_extension.proto";
import public "UnityType.proto";

option (file_type) = DATA_DEFINE;

enum CommonDataType
{
    option (cli_enum_sharp_type) = "ABC.Entity.CommonDataType";
    CommonDataType_None = 0;
    CommonDataType_Float = 1;
    CommonDataType_Int = 2;
    CommonDataType_Bool = 3;
    CommonDataType_String = 4;
    CommonDataType_Fixed = 5;
    CommonDataType_ULong = 6;
    CommonDataType_Object = 7;
    CommonDataType_Vector3 = 8;
}

enum TimeScaleType
{
    TimeScaleType_Normal = 0;
    TimeScaleType_UnityTimeline = 1;
    TimeScaleType_LogicTimeline = 2;
    TimeScaleType_Ability = 3;
    TimeScaleType_UIPage = 4;
    TimeScaleType_Tutorial = 5;
    TimeScaleType_Talk = 6;
}

message CommonData
{
    option (cli_message_sharp_type) = "ABC.Entity.CommonData";

    CommonDataType DataType = 1 [(field_gen_policy) = FIELD_SERVER];
    float FloatValue = 2 [(field_gen_policy) = FIELD_SERVER];
    int32 IntValue = 3 [(field_gen_policy) = FIELD_SERVER];
    bool BoolValue = 4 [(field_gen_policy) = FIELD_SERVER];
    string StringValue = 5 [(field_gen_policy) = FIELD_SERVER];
    fixed FixedValue = 6 [(field_gen_policy) = FIELD_SERVER];
    uint64 ULongValue = 7 [(field_gen_policy) = FIELD_SERVER];
}

message VariableConfig
{
    bool IsConstant = 1;
    bool InitializeWhenSkillRefresh = 2[(cli_default_value) = "true", (cli_field_attributes) = "ShowIfClass('ChsSkillConfig')"];
}

message SingleVariableConfig
{
    option (super_field_name) = "Base";
    VariableConfig Base = 1;

    CommonData Data = 2 [(cli_default_value) = "new()"];
}

message RankVariableConfig
{
    option (super_field_name) = "Base";
    VariableConfig Base = 1;

    CommonDataType DataType = 2;
    repeated float FloatValues = 3  [(cli_field_attributes) = "ShowIf('@this.DataType == CommonDataType.Float')"];
    repeated int32 IntValues = 4    [(cli_field_attributes) = "ShowIf('@this.DataType == CommonDataType.Int')"];
    repeated bool BoolValues = 5    [(cli_field_attributes) = "ShowIf('@this.DataType == CommonDataType.Bool')"];
    repeated fixed FixedValues = 6  [(cli_field_attributes) = "ShowIf('@this.DataType == CommonDataType.Fixed')"];
    repeated uint64 ULongValues = 7 [(cli_field_attributes) = "ShowIf('@this.DataType == CommonDataType.ULong')"];
}

