import os
def read_varint(b, i):
    r=0; s=0
    while True:
        x=b[i]; i+=1
        r|=(x&0x7F)<<s
        if not x&0x80: return r,i
        s+=7
def scan(b, depth=0, maxdepth=3):
    """打印前几层 wire format 结构(不递归太深)"""
    i=0; n=0
    while i<len(b) and n<12:
        tag,i=read_varint(b,i)
        fnum,wt=tag>>3,tag&7
        if wt==0:
            v,i=read_varint(b,i)
            print("  "*depth+f"f{fnum} varint={v}")
        elif wt==1: i+=8; print("  "*depth+f"f{fnum} fixed64")
        elif wt==2:
            ln,i=read_varint(b,i)
            payload=b[i:i+ln]; i+=ln
            try: t=payload.decode('utf-8'); printable=all(c.isprintable() or c in '\n\r\t' for c in t)
            except: printable=False
            if printable and len(t)<60: print("  "*depth+f"f{fnum} str={t!r}")
            else: print("  "*depth+f"f{fnum} bytes[{ln}]"); 
            if depth<maxdepth and not printable: scan(payload,depth+1,maxdepth)
        elif wt==5: i+=4; print("  "*depth+f"f{fnum} fixed32")
        else: print("  "*depth+f"f{fnum} WT{wt}?"); return
        n+=1
    if i<len(b): print("  "*depth+f"...({len(b)-i} more bytes)")

